import Foundation

struct Workout {

    struct Exercise: Identifiable {
        let id: UUID
        let name: String
        let description: String
        let image: String
        let equipment: [Equipment]
        let targetAreas: [TargetArea]
        let workoutTypes: [WorkoutType]
        init(name: String, description: String, image: String, equipment: [Equipment], targetAreas: [TargetArea], workoutTypes: [WorkoutType]) {
            self.id = UUID()
            self.name = name
            self.description = description
            self.image = image
            self.equipment = equipment
            self.targetAreas = targetAreas
            self.workoutTypes = workoutTypes
        }
    }
    
    func getExercises(targetArea: TargetArea, workoutType: WorkoutType, equipment: Equipment) -> [Exercise] {
        return exercises.filter { exercise in
            exercise.targetAreas.contains(targetArea) &&
            exercise.workoutTypes.contains(workoutType) &&
            exercise.equipment.contains(equipment)
        }
    }

